# Defining the blueprint
class Student:
    def __init__(self, name, marks):
        # Instance attributes
        self.name = name
        self.marks = marks  # List of numeric marks

    # Instance methods
    def calculate_total(self):
        return sum(self.marks)

    def calculate_average(self):
        return self.calculate_total() / len(self.marks) if self.marks else 0.0

    def is_pass(self, threshold=50):
        return self.calculate_average() >= threshold

    def display_card(self):
        status = 'PASS' if self.is_pass() else 'FAIL'
        print(f"{self.name:<10} | Avg: {self.calculate_average():>5.1f} | Status: {status}")

# Instantiating distinct objects
s1 = Student("Divya", [85, 92, 78])
s2 = Student("Karan", [45, 52, 48])

print("===== STUDENT REPORT CARDS =====")
s1.display_card()
s2.display_card()
